grid = [[8]*22 for _ in range(26)]
# Panel A: 9x6 canvas, 3x3 motif anchored at its top-right.
a = [[0,1,0],[1,0,1],[1,1,0]]
for r in range(2,11):
    for c in range(3,9):
        grid[r][c] = a[(r-2)%3][(c-3)%3]
# Panel B: 8x6 canvas, 2x2 motif anchored at bottom-left.
b = [[4,0],[4,4]]
for r in range(4,12):
    for c in range(13,19):
        grid[r][c] = b[(r-4)%2][(c-13)%2]
# Panel C: 6x8 canvas, 3x4 motif anchored at bottom-right.
cpat = [[3,0,3,3],[0,3,0,3],[3,3,0,3]]
for r in range(16,22):
    for c in range(3,11):
        grid[r][c] = cpat[(r-16)%3][(c-3)%4]
import json
assert len(grid)==26 and all(len(row)==22 for row in grid)
print(json.dumps(grid, separators=(',',':')))
